/* Custom HTML Block - QR Code Generator (CSS) */
/* Paste this in a <style> tag or external CSS file */

.qr-block-container {
    max-width: 400px;
    margin: 20px auto;
    padding: 25px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    text-align: center;
}

.qr-block-header {
    color: white;
    margin-bottom: 20px;
}

.qr-block-header h3 {
    margin: 0 0 8px 0;
    font-size: 22px;
    font-weight: 700;
    color: white;
}

.qr-block-header p {
    margin: 0;
    font-size: 13px;
    opacity: 0.9;
}

.qr-display-box {
    background: white;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 15px;
}

.qr-code-wrapper {
    display: flex;
    justify-content: center;
    margin: 15px 0;
}

.qr-label {
    font-size: 14px;
    color: #000;
    margin-top: 12px;
    font-weight: 700;
}

.qr-link-display {
    font-size: 11px;
    color: rgba(0, 0, 0, 0.5);
    margin-top: 8px;
    word-break: break-all;
    padding: 8px;
    background: rgba(0, 0, 0, 0.05);
    border-radius: 6px;
}

.qr-actions {
    display: flex;
    gap: 10px;
    justify-content: center;
}

.qr-btn {
    flex: 1;
    padding: 12px 20px;
    border: none;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    color: white;
}

.qr-btn-download {
    background: #28a745;
    box-shadow: 0 4px 15px rgba(40, 167, 69, 0.4);
}

.qr-btn-download:hover {
    background: #218838;
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(40, 167, 69, 0.6);
}

.qr-btn-download:active {
    transform: translateY(0);
}

.qr-btn-copy {
    background: #007bff;
    box-shadow: 0 4px 15px rgba(0, 123, 255, 0.4);
}

.qr-btn-copy:hover {
    background: #0056b3;
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0, 123, 255, 0.6);
}

.qr-btn-copy:active {
    transform: translateY(0);
}

/* Responsive Design */
@media (max-width: 500px) {
    .qr-block-container {
        margin: 10px;
        padding: 20px;
    }
    
    .qr-actions {
        flex-direction: column;
    }
    
    .qr-btn {
        width: 100%;
    }
}

