}

.icon-wrapper {
    width: 40px;
    height: 40px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
    flex-shrink: 0;
}

.permission-icon {
    width: 22px;
    height: 22px;
    color: #4a90e2;
}

.card-title {
