    padding: 0;
}

.card-description {
    margin: 0;
    font-size: 13px;
    color: #6c757d;
    line-height: 1.4;
}

/* Responsive Design */
@media (max-width: 480px) {
    .permission-card {
        max-width: 100%;
    }
}

script:
// Add smooth scroll animation on page load
document.addEventListener('DOMContentLoaded', function() {
  const cards = document.querySelectorAll('.attendance-card');
  
  cards.forEach((card, index) => {
    // Add staggered entrance animation
    card.style.opacity = '0';
    card.style.transform = 'translateY(20px)';
    
    setTimeout(() => {
      card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
      card.style.opacity = '1';
      card.style.transform = 'translateY(0)';
    }, index * 150);
  });

  // Add click tracking (optional)
  const buttons = document.querySelectorAll('.card-button');
  buttons.forEach(button => {
    button.addEventListener('click', function(e) {
      const cardTitle = this.closest('.attendance-card').querySelector('.card-title').textContent;
      console.log(`Navigating to: ${cardTitle}`);
      // You can add analytics tracking here if needed
    });
  });

  // Add ripple effect on button click
  buttons.forEach(button => {
    button.addEventListener('mousedown', function(e) {
      const ripple = document.createElement('span');
      const rect = this.getBoundingClientRect();
      const size = Math.max(rect.width, rect.height);
      const x = e.clientX - rect.left - size / 2;
      const y = e.clientY - rect.top - size / 2;
      
      ripple.style.width = ripple.style.height = size + 'px';
      ripple.style.left = x + 'px';
      ripple.style.top = y + 'px';
      ripple.classList.add('ripple-effect');
      
      this.appendChild(ripple);
      
      setTimeout(() => ripple.remove(), 600);
    });
  });
});

// Optional: Add CSS for ripple effect dynamically
const style = document.createElement('style');
style.textContent = `
  .card-button {
    position: relative;
    overflow: hidden;
  }
  
  .ripple-effect {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.6);
    transform: scale(0);
    animation: ripple-animation 0.6s ease-out;
    pointer-events: none;
  }
  
  @keyframes ripple-animation {
    to {
      transform: scale(4);
      opacity: 0;
    }
  }
`;
document.head.appendChild(style);

style:
.attendance-cards-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  padding: 16px;
  max-width: 700px;
  margin: 0 auto;
}
.attendance-card {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  position: relative;
  overflow: hidden;
  color: white;
}
.attendance-card::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 0%, transparent 70%);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.attendance-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.2);
}
.attendance-card:hover::before {
  opacity: 1;
}
.student-card {
  background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
}
.employee-card {
  background: linear-gradient(135deg, #134e5e 0%, #71b280 100%);
}
.card-icon {
  width: 48px;
  height: 48px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  backdrop-filter: blur(10px);
}
.card-icon svg {
  color: white;
  width: 32px;
  height: 32px;
}
.card-title {
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 8px 0;
  color: white;
}
.card-description {
  font-size: 12px;
  line-height: 1.4;
  margin: 0 0 16px 0;
  opacity: 0.9;
  color: white;
}
.card-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(255, 255, 255, 0.25);
  color: white;
  padding: 8px 16px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: 600;
  font-size: 12px;
  transition: background 0.3s ease, transform 0.2s ease;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.3);
}
.card-button:hover {
  background: rgba(255, 255, 255, 0.35);
  transform: translateX(4px);
  color: white;
}
.card-button svg {
  transition: transform 0.3s ease;
}
.card-button:hover svg {
  transform: translateX(4px);
}
@media (max-width: 768px) {
  .attendance-cards-container {
    grid-template-columns: 1fr;
    padding: 12px;
  }
  
  .attendance-card {
    padding: 16px;
  }
}
